{"path": "robot_name.py", "content": "import random
import string


class Robot:
    """A robot with a unique random name of the form AA000."""

    _used_names = set()

    def __init__(self):
        self.name = None
        self.reset()

    @classmethod
    def _generate_name(cls):
        if len(cls._used_names) >= 26 * 26 * 1000:
            raise RuntimeError("No robot names left")
        while True:
            name = "".join(random.choice(string.ascii_uppercase) for _ in range(2)) + "".join(
                random.choice(string.digits) for _ in range(3)
            )
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name

    def reset(self):
        """Wipe the name and assign a fresh, unique one."""
        old_name = self.name
        # Generate the new name before releasing the old one, so it always differs.
        self.name = self._generate_name()
        if old_name is not None:
            self._used_names.discard(old_name)
